mapper.select:
SELECT distinct srp.id, srp.code, srp.type, srp.return_logistic_code AS returnLogisticCode, srp.link_status AS linkStatus, srp.source_id AS sourceId, srp.source_code AS sourceCode, srp.source_type AS sourceType, srp.third_code AS thirdCode, srp.inventory_org_id AS inventoryOrgId, srp.inventory_org_name AS inventoryOrgName, srp.warehouse_id AS warehouseId, srp.warehouse_name AS warehouseName, srp.return_type_dict AS returnTypeDict, srp.return_instock_time AS returnInstockTime, srp.operate_time AS operateTime, srp.remark, srp.version, srp.create_user_id AS createUserId, srp.create_user_name AS createUserName, srp.create_time AS createTime, srp.update_user_id AS updateUserId, srp.update_user_name AS updateUserName, srp.update_time AS updateTime FROM so_return_prestock srp left join so_return_prestock_detail dt on dt.main_id = srp.id and dt.is_deleted = FALSE WHERE ${params.sqlMap.default} AND srp.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
srp.return_instock_time DESC
